// secureCookie keeps a session off the wire in clear text everywhere but
// localhost, where the app runs plain HTTP in development and in tests.
// r.URL.Host is empty on a request a server was handed, so the Host header
// names the host here; it carries the port, so "localhost:3000" is localhost
// and "localhost.evil.test" is not.
func secureCookie(r *http.Request) bool {
	if r.TLS != nil {
		return true
	}
	switch strings.Trim(hostnameOf(r.Host), "[]") {
	case "localhost", "127.0.0.1", "::1":
		return false
	}
	return true
}

// hostnameOf cuts the port off a Host header. A bracketed IPv6 address keeps
// its brackets to itself, so only a colon after the closing one is a port; a
// bare ::1:80 cannot be told from its own port and is left as it stands.
func hostnameOf(host string) string {
	i := strings.LastIndexByte(host, ':')
	if i < 0 {
		return host
	}
	if j := strings.LastIndexByte(host, ']'); j >= 0 && j > i {
		return host[:j+1]
	}
	return host[:i]
}
