// Config is what the handler is built with.
type Config struct {
	// DataDir is where the app keeps its data (DATA_DIR, the data volume).
	DataDir string
	// Store overrides the SQLite store opened at DataDir/notes.db. Tests set
	// it; New opens the real one when it is nil.
	Store store.Store
}

// server holds the store every route works through.
type server struct {
	store store.Store
}

// New serves /healthz, the API under /api/ and the single-page app under
// /app/; / redirects to /app/. It opens the store at $DataDir/notes.db and
// runs its migrations, and answers a handler that fails every request when
// that fails: a process without its data has nothing to serve.
func New(cfg Config) http.Handler {
	st := cfg.Store
	if st == nil {
		var err error
		if st, err = store.Open(cfg.DataDir); err != nil {
			log.Printf("server: %v", err)
			return failHandler(err)
		}
	}
	s := &server{store: st}

	mux := http.NewServeMux()
	s.registerRoutes(mux)
	mux.Handle("/api/", s.apiAuth(http.NotFoundHandler()))
	mux.Handle("/app/", http.StripPrefix("/app", app()))
	mux.Handle("GET /{$}", http.RedirectHandler("/app/", http.StatusFound))
	return mux
}

// failHandler answers every request 500: New made it when the store could
// not open, so the process stays up for its probes and says why.
func failHandler(err error) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "data unavailable"})
		log.Printf("server: request without a store: %v", err)
	})
}

