// noteIDFrom answers the {id} of the path; a value that is no positive
// number is 404, since no note can carry it.
func noteIDFrom(w http.ResponseWriter, r *http.Request) (int64, bool) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil || id < 1 {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
		return 0, false
	}
	return id, true
}

func (s *server) getNote(w http.ResponseWriter, r *http.Request) {
	userID, ok := s.userOf(r)
	if !ok {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
	}
	noteID, ok := noteIDFrom(w, r)
	if !ok {
		return
	}
	note, err := s.store.GetNote(noteID, userID)
	if err != nil {
		writeStoreError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, noteToJSON(note))
}

func (s *server) updateNote(w http.ResponseWriter, r *http.Request) {
	userID, ok := s.userOf(r)
	if !ok {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
	}
	noteID, ok := noteIDFrom(w, r)
	if !ok {
		return
	}
	req, ok := decodeNote(w, r)
	if !ok {
		return
	}
	tags, details := validateNote(req)
	if details != nil {
		writeValidationError(w, details)
		return
	}
	current, err := s.store.GetNote(noteID, userID)
	if err != nil {
		writeStoreError(w, err)
		return
	}
	if req.Tags == nil {
		tags = current.Tags
	}
	note, err := s.store.UpdateNote(noteID, userID, strings.TrimSpace(req.Title), req.Body, tags)
	if err != nil {
		writeStoreError(w, err)
		return
	}
	writeJSON(w, http.StatusOK, noteToJSON(note))
}

