	userID, ok := s.userOf(r)
	if !ok {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
	}
	noteID, ok := noteIDFrom(w, r)
	if !ok {
		return
	}
	if err := s.store.DeleteNote(noteID, userID); err != nil {
		writeStoreError(w, err)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// tagCountJSON is one of the user's tags with how many of their notes carry it.
type tagCountJSON struct {
	Tag   string `json:"tag"`
	Count int    `json:"count"`
}

func (s *server) listTags(w http.ResponseWriter, r *http.Request) {
	userID, ok := s.userOf(r)
	if !ok {
		writeJSON(w, http.StatusUnauthorized, map[string]string{"error": "unauthorized"})
		return
	}
	counts, err := s.store.ListTags(userID)
	if err != nil {
		writeStoreError(w, err)
		return
	}
	out := make([]tagCountJSON, 0, len(counts))
	for _, tc := range counts {
		out = append(out, tagCountJSON{Tag: tc.Tag, Count: tc.Count})
	}
	writeJSON(w, http.StatusOK, map[string]any{"tags": out})
}

// writeStoreError answers the store's failure: a note that is not there, or
// not the caller's, is 404; anything else is 500 and goes to the log.
func writeStoreError(w http.ResponseWriter, err error) {
	if errors.Is(err, store.ErrNotFound) {
		writeJSON(w, http.StatusNotFound, map[string]string{"error": "not found"})
		return
	}
	log.Printf("server: %v", err)
	writeJSON(w, http.StatusInternalServerError, map[string]string{"error": "internal error"})
}

