// NoteEditor edits one note: its title, body and tags, with save and delete.
// The route is /notes/new for a note that does not exist yet.
export default function NoteEditor() {
  const { id } = useParams()
  const navigate = useNavigate()
  const isNew = !id || id === 'new'

  const [title, setTitle] = useState('')
  const [body, setBody] = useState('')
  const [tagText, setTagText] = useState('')
  const [loading, setLoading] = useState(!isNew)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [savedAt, setSavedAt] = useState('')

  const tags = useMemo(() => parseTags(tagText), [tagText])
  const issues = useMemo(() => noteIssues(title, body, tags), [title, body, tags])

  const load = useCallback(async () => {
    if (isNew) return
    setLoading(true)
    setError('')
    try {
      const res = await fetch(`/api/notes/${id}`)
      if (!res.ok) {
        setError(await readError(res))
        return
      }
      const note = (await res.json()) as Note
      setTitle(note.title)
      setBody(note.body)
      setTagText(note.tags.join(', '))
      setSavedAt(note.updated_at)
    } catch {
      setError('the note could not be loaded')
    } finally {
      setLoading(false)
    }
  }, [id, isNew])

  useEffect(() => {
    void load()
  }, [load])

  async function save(event: FormEvent) {
    event.preventDefault()
    if (issues.length > 0) {
      setError(issues.join('; '))
      return
    }
    setSaving(true)
    setError('')
    const method = isNew ? 'POST' : 'PUT'
    const path = isNew ? '/api/notes' : `/api/notes/${id}`
    try {
      const res = await fetch(path, {
        method,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: title.trim(), body, tags }),
      })
      if (!res.ok) {
        setError(await readError(res))
        return
      }
      const note = (await res.json()) as Note
      setSavedAt(note.updated_at)
      if (isNew) navigate(`/notes/${note.id}`, { replace: true })
    } catch {
      setError('the note could not be saved')
    } finally {
      setSaving(false)
    }
  }

  async function remove() {
    if (isNew) {
      navigate('/notes')
      return
    }
    setSaving(true)
    setError('')
    try {
      const res = await fetch(`/api/notes/${id}`, { method: 'DELETE' })
      if (!res.ok && res.status !== 404) {
        setError(await readError(res))
        return
      }
      navigate('/notes')
    } catch {
      setError('the note could not be deleted')
    } finally {
      setSaving(false)
    }
  }

  return (
    <main>
      <h1>{isNew ? 'New note' : `Edit note ${id}`}</h1>
      <p>
        <Link to="/notes">all notes</Link>
      </p>
      {loading && <p>Loading…</p>}
      <form onSubmit={save}>
        <label htmlFor="title">Title</label>
        <input
          id="title"
          name="title"
          value={title}
          maxLength={MAX_TITLE}
          onChange={(e) => setTitle(e.target.value)}
        />
        <label htmlFor="body">Body</label>
        <textarea id="body" name="body" rows={10} value={body} onChange={(e) => setBody(e.target.value)} />
        <label htmlFor="tags">Tags</label>
        <input
          id="tags"
          name="tags"
          value={tagText}
          placeholder="go, work"
          onChange={(e) => setTagText(e.target.value)}
        />
        <p aria-live="polite">{`${tags.length} tag${tags.length === 1 ? '' : 's'}: ${tags.join(', ') || 'none'}`}</p>
        {error && (
          <p role="alert">{error}</p>
        )}
        {savedAt && !error && <p>Saved {savedAt}</p>}
        <button type="submit" disabled={saving || loading}>
          Save
        </button>
        <button type="button" disabled={saving} onClick={remove}>
          Delete
        </button>
      </form>
    </main>
  )
}

func login(t *testing.T, st store.Store, name string) func(method, path string, body any) *http.Request {
	t.Helper()
	user, err := st.GetUserByUsername(name)
	if errors.Is(err, store.ErrNotFound) {
		user, err = st.CreateUser(name, "hash")
	}
	if err != nil {
		t.Fatalf("user %s: %v", name, err)
	}
	token, err := store.NewToken(22)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := st.CreateSession(user.ID, token, time.Now().UTC().Add(time.Hour)); err != nil {
		t.Fatalf("session for %s: %v", name, err)
	}
	return func(method, path string, body any) *http.Request {
		var r io.Reader
		if body != nil {
			data, err := json.Marshal(body)
			if err != nil {
				t.Fatalf("marshal %v: %v", body, err)
			}
			r = bytes.NewReader(data)
		}
		req, err := http.NewRequest(method, path, r)
		if err != nil {
			t.Fatal(err)
		}
		if body != nil {
			req.Header.Set("Content-Type", "application/json")
		}
		req.AddCookie(&http.Cookie{Name: "session", Value: token})
		return req
	}
}

// do sends a request and reads the whole answer.
func do(t *testing.T, req *http.Request) (int, []byte) {
	t.Helper()
	res, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("%s %s: %v", req.Method, req.URL.Path, err)
	}
	defer func() { _ = res.Body.Close() }()
	body, err := io.ReadAll(res.Body)
	if err != nil {
		t.Fatalf("read the body of %s %s: %v", req.Method, req.URL.Path, err)
	}
	return res.StatusCode, body
}

